import re

def create_agent_with_tools(llm, tools):
    registry = {t["name"]: t["func"] for t in tools}
    descriptions = {t["name"]: t["description"] for t in tools}
    def agent(query):
        for name, desc in descriptions.items():
            if any(kw in query.lower() for kw in desc.lower().split()):
                try:
                    result = registry[name](query)
                    return {"tool": name, "result": result}
                except Exception as e:
                    return {"tool": name, "error": str(e)}
        return {"tool": None, "result": llm(query)}
    return agent
